{"command":"$lines = Get-Content .\input\session.jsonl
for ($i=0; $i -lt $lines.Count; $i++) {
  $o = $lines[$i] | ConvertFrom-Json
  $type = $o.type
  $extra = ""
  if ($type -eq "response_item") {
    $p = $o.payload
    if ($p.role -eq "user") { $extra = "USER: " + ($p.content | ConvertTo-Json -Compress -Depth 10) }
    elseif ($p.role -eq "assistant") { $extra = "ASSISTANT msg id=" + $p.id }
  } elseif ($type -eq "event_msg") {
    $extra = $o.payload.type
  }
  "LINE $i [$type] $extra"
}"}

{"command":"$content = [System.IO.File]::ReadAllText('<repo>-bench\ab-continuation\sandboxes-r7full\formal-case-01-A\input\session.jsonl', [System.Text.Encoding]::UTF8)
$lines = $content -split "`n"
Write-Host "total lines: $($lines.Count)"
$out = New-Object System.Collections.Generic.List[string]
foreach ($line in $lines) {
  $t = $line.Trim()
  if ($t.Length -eq 0) { continue }
  try { $o = $t | ConvertFrom-Json -ErrorAction Stop } catch { $out.Add("PARSE_ERROR line"); continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'message' -and ($o.payload.role -eq 'assistant')) {
    foreach ($c in $o.payload.content) {
      if ($c.type -eq 'output_text' -or $c.type -eq 'input_text') {
        $short = ($c.text -replace "\r?\n", " " )
        if ($short.Length -gt 3000) { $short = $short.Substring(0,3000) + "...[TRUNC]" }
        $out.Add("[$($o.timestamp)] role=$($o.payload.role) phase=$($o.payload.phase) :: $short")
      }
    }
  }
}
$out | ForEach-Object { $_ }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$content = [System.IO.File]::ReadAllText('<repo>-bench\ab-continuation\sandboxes-r7full\formal-case-01-A\input\session.jsonl', [System.Text.Encoding]::UTF8)
$lines = $content -split "`n"
$out = New-Object System.Collections.Generic.List[string]
foreach ($line in $lines) {
  $t = $line.Trim(); if ($t.Length -eq 0) { continue }
  try { $o = $t | ConvertFrom-Json -ErrorAction Stop } catch { continue }
  if ($o.type -eq 'response_item' -and $o.payload.type -eq 'message') {
    $role = $o.payload.role; $phase = $o.payload.phase
    if ($role -eq 'assistant') {
      foreach ($c in $o.payload.content) {
        if ($c.type -eq 'output_text' -or $c.type -eq 'input_text') {
          $short = ($c.text -replace "\r?\n", " ")
          if ($short.Length -gt 2500) { $short = $short.Substring(0,2500) + "...[TRUNC]" }
          $out.Add("[$($o.timestamp)] ASSISTANT/$phase :: $short")
        }
      }
    } elseif ($role -eq 'user') {
      foreach ($c in $o.payload.content) {
        if ($c.type -eq 'input_text') { $out.Add("[$($o.timestamp)] USER :: " + (($c.text -replace "\r?\n"," ") )) }
      }
    }
  }
}
$out | ForEach-Object { $_ }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
foreach ($p in @('src','src\agents','src\cli','src\surfaces','src\runtime','src\runtime\claude','electron')) {
  $root = Join-Path '.\workspace' $p
  Write-Host "=== $p ==="
  if (Test-Path $root) { Get-ChildItem $root -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { "{0}`t{1}`t{2}" -f $_.Length, $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'), $_.FullName.Replace((Get-Location).Path + '\workspace\','') } } else { Write-Host '(missing)' }
}"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Get-ChildItem .\workspace\web\src\margin -File -ErrorAction SilentlyContinue | ForEach-Object { "{0}`t{1}`t{2}" -f $_.Name, $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'), $_.Length }
Write-Host '--- docs recent ---'
Get-ChildItem .\workspace\docs -Recurse -File | Where-Object { $_.LastWriteTime -gt [datetime]'2026-09-07 02:00' } | ForEach-Object { "{0}`t{1}" -f $_.FullName.Replace((Get-Location).Path+'\workspace\',''), $_.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss') }
Write-Host '--- evaluation dir ---'
Get-ChildItem .\workspace\evaluation -Recurse -File -ErrorAction SilentlyContinue | Select-Object -First 20 | ForEach-Object { $_.FullName.Replace((Get-Location).Path+'\workspace\','') }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$content = [System.IO.File]::ReadAllText('<repo>-bench\ab-continuation\sandboxes-r7full\formal-case-01-A\input\session.jsonl', [System.Text.Encoding]::UTF8)
$lines = $content -split "`n"
$out = New-Object System.Collections.Generic.List[string]
foreach ($line in $lines) {
  $t = $line.Trim(); if ($t.Length -eq 0) { continue }
  try { $o = $t | ConvertFrom-Json -ErrorAction Stop } catch { continue }
  if ($o.type -eq 'event_msg' -and $o.payload.type -eq 'item_completed' -and $o.payload.item.type -eq 'CommandExecution') {
    $cmd = ($o.payload.item.parsed_cmd | ForEach-Object { $_.cmd }) -join ' ; '
    $status = $o.payload.item.status
    if ($cmd -match 'git|commit|add|agent|node --test|build|make|smoke|install|Start-Process|Get-Process') {
      $cmdShort = ($cmd -replace '\s+',' ')
      if ($cmdShort.Length -gt 260) { $cmdShort = $cmdShort.Substring(0,260) + '...' }
      $out.Add("[$($o.timestamp)] $status :: $cmdShort")
    }
  }
}
$out | ForEach-Object { $_ }"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$content = [System.IO.File]::ReadAllText('<repo>-bench\ab-continuation\sandboxes-r7full\formal-case-01-A\input\session.jsonl', [System.Text.Encoding]::UTF8)
$lines = $content -split "`n"
foreach ($line in $lines) {
  $t = $line.Trim(); if ($t.Length -eq 0) { continue }
  try { $o = $t | ConvertFrom-Json -ErrorAction Stop } catch { continue }
  if ($o.type -eq 'event_msg' -and $o.payload.type -eq 'item_completed') {
    $item = $o.payload.item
    if ($item.type -eq 'CommandExecution') {
      $cmd = ($item.parsed_cmd | ForEach-Object { $_.cmd }) -join ' ; '
      if ($cmd -match 'marginR3Board|asar|smoke|margin-0.1.0 Setup.exe|agentSourceRegistry') {
        Write-Host "=== $($o.timestamp) status=$($item.status) ==="
        $cand = $item.stdout
        if ($cand -match 'TAP version 13') {
          $m = [regex]::Matches($cand, '# (tests|pass|fail|skipped|cancelled|todo) (\d+)')
          $m | ForEach-Object { Write-Host $_.Value }
          $cand -split "`n" | Where-Object { $_ -match 'not ok ' } | Select-Object -First 8 | ForEach-Object { Write-Host ("FAIL> " + $_.Trim()) }
        } elseif ($cand -match 'Setup.exe|\.zip|\.nupkg|artifact|asar') {
          ($cand -split "`n" | Where-Object { $_ -match 'Setup.exe|zip|nupkg|app.asar|sourceRegistry|agentSourceCli|not ok|Error|smoke|margin\.exe|PASS|fail' } | Select-Object -First 15) | ForEach-Object { Write-Host $_.Trim() }
        } else { ($cand -split "`n" | Select-Object -First 12) | ForEach-Object { Write-Host $_.Trim() } }
        Write-Host ""
      }
    }
  }
}"}
